    "Flèche, Double Flèche, Chevron, Étoile.": "Pil, Dubbelpil, Chevron, Stjärna.",
    "Fournit l'énergie. Sans assez d'énergie, la production ralentit.": "Ger energi. Utan tillräckligt med energi saktas produktionen ner.",
    "Gains de base. Sur les maps des firmes, les crédits sont multipliés : ×2 en X-1 à X-4, ×1,5 en X-5, ×1,25 en X-6 à X-8. Boosters, formations, pilote et modules s'ajoutent.": "Grundvinster. På företagens kartor multipliceras krediterna: ×2 i X-1 till X-4, ×1,5 i X-5, ×1,25 i X-6 till X-8. Boosters, formationer, pilot och moduler tillkommer.",
    "Garde une config 2 de fuite et utilise ISH / IEM.": "Ha en flyktkonfig 2 och använd ISH / EMP.",
    "Général, expérience, honneur, vagues Eternal, grade.": "Allmänt, erfarenhet, ära, Eternal-vågor, grad.",
    "Générateurs de bouclier": "Sköldgeneratorer",
    "Générateurs de vitesse": "Hastighetsgeneratorer",
    "gros NPC, PvP, crédits ×1,25.": "stora NPC, PvP, krediter ×1,25.",
    "Hangars et configurations": "Hangarer och konfigurationer",
    "Honneur gagné +10 % pendant 1 h.": "Erhållen ära +10 % i 1 h.",
    "Honneur gagné +10 %,": "Erhållen ära +10 %,",
    "Honneur gagné +50 % pendant 1 h.": "Erhållen ära +50 % i 1 h.",
    "IEM : casse les verrouillages ennemis, retire gel et ralentissement (3 s).": "EMP: bryter fiendelåsningar, tar bort frysning och saktning (3 s).",
    "IEM, ISH et contrôles": "EMP, ISH och kontroller",
    "IEM, ISH, camouflage après un kill.": "EMP, ISH, kamouflage efter en kill.",
    "Il gagne de l'XP avec toi ; les gears de niveau 2, 3 et 4 demandent un P.E.T de niveau 4, 8 et 20.": "Den får XP med dig; gears på nivå 2, 3 och 4 kräver en P.E.T på nivå 4, 8 och 20.",
    "Il garde les stats du vaisseau de base. Certains designs ajoutent un bonus ou une compétence propre, affichés en boutique.": "Den behåller basskeppets stats. Vissa designer lägger till en egen bonus eller förmåga, som visas i butiken.",
    "Il ne quitte jamais un NPC verrouillé pour une box, sauf si tu l'autorises.": "Den lämnar aldrig en låst NPC för en låda, om du inte tillåter det.",
    "Il porte ses propres lasers et générateurs (certains sont réservés au P.E.T).": "Den bär egna lasrar och generatorer (vissa är reserverade för P.E.T).",
    "Illuminé": "Upplyst",
    "Ils gagnent une part de ton expérience et montent jusqu'au niveau": "De får en del av din erfarenhet och går upp till nivå",
    "Initié Blacklight": "Blacklight-invigd",
    "Invite un joueur ; l'invitation expire après 15 s.": "Bjud in en spelare; inbjudan går ut efter 15 s.",
    "invulnérable 3 s ; ton propre verrouillage est gardé.": "osårbar 3 s; din egen låsning behålls.",
    "ISH : invulnérabilité totale pendant 3 s.": "ISH: total osårbarhet i 3 s.",
    "Je n'inflige aucun dégât": "Jag gör ingen skada",
